-- Additive only. Run manually AFTER the documented audit, backup and isolated test.
-- No IF NOT EXISTS: a collision must stop migration, never adopt an unknown table.
CREATE TABLE web_schema_versions (version INT PRIMARY KEY, applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE web_categories (id VARCHAR(100) PRIMARY KEY, slug VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, short VARCHAR(40) NOT NULL, description TEXT NOT NULL, image VARCHAR(300) NOT NULL, parent_id VARCHAR(100) NULL, published BOOLEAN NOT NULL, sort_order INT NOT NULL, version INT NOT NULL DEFAULT 1, FOREIGN KEY(parent_id) REFERENCES web_categories(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE web_products (id VARCHAR(100) PRIMARY KEY, sku VARCHAR(100) NOT NULL UNIQUE, category_id VARCHAR(100) NOT NULL, body JSON NOT NULL, version INT NOT NULL DEFAULT 1, FOREIGN KEY(category_id) REFERENCES web_categories(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE web_variations (id VARCHAR(36) PRIMARY KEY, product_id VARCHAR(100) NOT NULL, sku VARCHAR(100) NOT NULL UNIQUE, body JSON NOT NULL, sort_order INT NOT NULL, FOREIGN KEY(product_id) REFERENCES web_products(id) ON DELETE RESTRICT, INDEX web_variations_product(product_id,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE web_variation_prices (variation_id VARCHAR(36) PRIMARY KEY, mrp DECIMAL(10,2) NULL, selling_price DECIMAL(10,2) NULL, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(variation_id) REFERENCES web_variations(id) ON DELETE CASCADE, CHECK(mrp >= 0 AND selling_price >= 0 AND selling_price <= mrp), CHECK((mrp IS NULL) = (selling_price IS NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE web_price_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, variation_id VARCHAR(36) NOT NULL, old_mrp DECIMAL(10,2) NULL, old_selling_price DECIMAL(10,2) NULL, new_mrp DECIMAL(10,2) NULL, new_selling_price DECIMAL(10,2) NULL, actor VARCHAR(100) NOT NULL, changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX web_price_history_variation(variation_id,changed_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE web_media (url VARCHAR(200) PRIMARY KEY, mime VARCHAR(80) NOT NULL, byte_length INT UNSIGNED NOT NULL, sha256 CHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE web_product_images (product_id VARCHAR(100) NOT NULL, variation_id VARCHAR(36) NOT NULL DEFAULT '', url VARCHAR(200) NOT NULL, sort_order INT NOT NULL, PRIMARY KEY(product_id,variation_id,sort_order), FOREIGN KEY(product_id) REFERENCES web_products(id) ON DELETE RESTRICT, FOREIGN KEY(url) REFERENCES web_media(url) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE web_product_pdfs (product_id VARCHAR(100) PRIMARY KEY, url VARCHAR(200) NOT NULL, FOREIGN KEY(product_id) REFERENCES web_products(id) ON DELETE RESTRICT, FOREIGN KEY(url) REFERENCES web_media(url) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE web_enquiries (id VARCHAR(36) PRIMARY KEY, body JSON NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO web_schema_versions(version) VALUES(1);
